import { SchemaScript } from "./schema-script";
import type { HowToStep } from "./types";

type HowToBlockProps = {
  title: string;
  intro?: string;
  steps: HowToStep[];
  includeHowToSchema?: boolean;
};

export function HowToBlock({
  title,
  intro,
  steps,
  includeHowToSchema = false,
}: HowToBlockProps) {
  const howToSchema = {
    "@context": "https://schema.org",
    "@type": "HowTo",
    name: title,
    ...(intro ? { description: intro } : {}),
    step: steps.map((step) => ({
      "@type": "HowToStep",
      name: step.title,
      text: step.detail,
    })),
  };

  return (
    <section aria-labelledby="how-to-heading" className="space-y-8">
      {includeHowToSchema ? <SchemaScript schema={howToSchema} /> : null}
      <header className="space-y-4">
        <h2 id="how-to-heading" className="text-3xl leading-tight tracking-tight text-[#EAEAEA] md:text-5xl">
          {title}
        </h2>
        {intro ? <p className="max-w-4xl text-lg text-[#B0B0B0]">{intro}</p> : null}
      </header>

      <ol className="space-y-8 border-t border-divider pt-8">
        {steps.map((step, index) => (
          <li key={step.title} className="grid gap-3 border-b border-divider pb-8 md:grid-cols-[auto_1fr] md:gap-8">
            <span className="text-sm uppercase tracking-[0.18em] text-[#EAEAEA]/70">
              {(index + 1).toString().padStart(2, "0")}
            </span>
            <div>
              <h3 className="text-xl text-[#EAEAEA]">{step.title}</h3>
              <p className="pt-3 max-w-4xl text-base leading-relaxed text-[#B0B0B0] md:text-lg">
                {step.detail}
              </p>
            </div>
          </li>
        ))}
      </ol>
    </section>
  );
}
